			codeFrame.Frame.Parent = window.GuiElems.Content
	
			local execButtons = setupExecutorButtons(window, codeFrame)
			local consoleButtons = setupConsoleButtons(window)
	
			local navButtons = {
				console = Instance.new("TextButton", window.GuiElems.Content)
			}
	
			navButtons.console.Position = UDim2.new(0.5, 0, 0, 0)
			navButtons.console.Size = UDim2.new(0.5, 0, 0, 20)
			navButtons.console.Text = "Console"
			navButtons.console.TextColor3 = Color3.new(1,1,1)
			navButtons.console.BackgroundTransparency = 1
	
			local function showExecutor()
				codeFrame.Frame.Visible = true
				execButtons.clear.Visible = true
				execButtons.execute.Visible = true
				execButtons.execConsole.Visible = true
	
				consoleButtons.clear.Visible = false
				consoleButtons.update.Visible = false
				consoleButtons.toggle.Visible = false
				consoleButtons.toggle.Parent.Cons.Visible = false
			end
	
			local function showConsole()
				codeFrame.Frame.Visible = false
				execButtons.clear.Visible = false
				execButtons.execute.Visible = false
				execButtons.execConsole.Visible = false
	
				consoleButtons.clear.Visible = true
				consoleButtons.update.Visible = true
				consoleButtons.toggle.Visible = true
				consoleButtons.toggle.Parent.Cons.Visible = true
			end
	
			execButtons.executor.Parent.ExecuteConsole.MouseButton1Click:Connect(function()
				local source = codeFrame:GetText() 
				showConsole()
				local func, err = loadstring(source)
	            if func then
	            	pcall(func)
	            end
			end)
			execButtons.executor.Parent.ExecuteConsole.MouseButton2Click:Connect(function()
	
			end)
			execButtons.executor.MouseButton1Click:Connect(showExecutor)
			navButtons.console.MouseButton1Click:Connect(showConsole)
	
			return window
		end)
	
