		-- Extract frame number from asset name
		local function getFrameNumber(assetId)
			local id = tonumber(assetId:match("%d+"))
			local success, info = pcall(MarketplaceService.GetProductInfo, MarketplaceService, id)
			if success and info and info.Name then
				local frameStr = info.Name:match("frame_(%d+)_delay")
				return tonumber(frameStr)
			end
			return nil
		end
	
		-- Build sorted table
		local sortedAssets = {}
	
		for _, asset in ipairs(MainTable) do
			local frame = getFrameNumber(asset)
			if frame then
				sortedAssets[frame] = asset
			end
		end
	
		-- Flipbook animation
		local frameRate = 0.02
	
		task.spawn(function()
			while true do
				for i = 1, #sortedAssets do
					ImageLabel.Image = sortedAssets[i]
					task.wait(frameRate)
				end
			end
		end)
		
