		Lib.CopyPath = (function(path)
			local window = Lib.Window.new()
			window:SetTitle("Path Finder - Copy Path")
			window:Resize(286, 41)
	
			local TextBox = Instance.new("TextBox")
			local UIPadding = Instance.new("UIPadding")
			TextBox.Parent = window.GuiElems.Content
			TextBox.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
			TextBox.BackgroundTransparency = 1.000
			TextBox.BorderColor3 = Color3.fromRGB(0, 0, 0)
			TextBox.BorderSizePixel = 0
			TextBox.Size = UDim2.new(1, 0, 1, 0)
			TextBox.ClearTextOnFocus = false
			TextBox.Font = Enum.Font.SourceSans
			TextBox.PlaceholderText = "Dex could not detect path."
			TextBox.Text = path and tostring(path) or ""
			TextBox.TextColor3 = Color3.fromRGB(255, 255, 255)
			TextBox.TextSize = 14.000
			TextBox.TextXAlignment = Enum.TextXAlignment.Left
	
			UIPadding.Parent = TextBox
			UIPadding.PaddingLeft = UDim.new(0.01, 0)
			UIPadding.PaddingTop = UDim.new(-0.1, 0)
	
			-- Shortcut listener
			local ctrlDown = false
			local inputConn, upConn
	
			inputConn = game:GetService("UserInputService").InputBegan:Connect(function(input, gameProcessed)
				if not gameProcessed then return end
	
				if input.KeyCode == Enum.KeyCode.LeftControl then
					ctrlDown = true
				elseif input.KeyCode == Enum.KeyCode.C and ctrlDown then
					wait(0.5)
					window:Close()
					inputConn:Disconnect()
					upConn:Disconnect()
				end
			end)
	
			upConn = game:GetService("UserInputService").InputEnded:Connect(function(input)
				if input.KeyCode == Enum.KeyCode.LeftControl then
					ctrlDown = false
				end
			end)
	
			return window
		end)
	
