			for _, plr in pairs(game.Players:GetPlayers()) do
				if model == plr.Character or model.Name == plr.Name then
					warn("[CreateViewPort] Skipping player-linked model.")
					return
				end
			end
	
			local function createViewPort(parent)
				local viewportFrame = Instance.new("ViewportFrame")
				viewportFrame.Parent = parent
				viewportFrame.Size = UDim2.new(1, 0, 1, -1)
				viewportFrame.Position = UDim2.new(0, 0, 0, 1)
				viewportFrame.BorderSizePixel = 0
				viewportFrame.BackgroundColor3 = Color3.fromRGB(42, 42, 42) 
				viewportFrame.BackgroundTransparency = 0 
				return viewportFrame
			end
			
			local viewportFrame = createViewPort(par)
			
			for _, child in ipairs(viewportFrame:GetChildren()) do
				if child:IsA("Model") or child:IsA("BasePart") then
					child:Destroy()
				end
			end
	
			model.Archivable = true
			local clonedObj = model:Clone()
			clonedObj.Parent = viewportFrame
	
			if clonedObj:IsA("Model") then
				if not clonedObj.PrimaryPart then
					local bboxCFrame, bboxSize = clonedObj:GetBoundingBox()
					local centerPart = Instance.new("Part")
					centerPart.Name = "__Center"
					centerPart.Anchored = true
					centerPart.CanCollide = false
					centerPart.Transparency = 1
					centerPart.Size = bboxSize
					centerPart.CFrame = bboxCFrame
					centerPart.Parent = clonedObj
					clonedObj.PrimaryPart = centerPart
				end
				clonedObj:SetPrimaryPartCFrame(CFrame.new(0, 0, 0))
			elseif clonedObj:IsA("BasePart") then
				clonedObj.Anchored = true
				clonedObj.CFrame = CFrame.new(0, 0, 0)
			end
	
			local camera = Instance.new("Camera")
			viewportFrame.CurrentCamera = camera
	
			local bboxCFrame, bboxSize
			if clonedObj:IsA("Model") then
				bboxCFrame, bboxSize = clonedObj:GetBoundingBox()
			else
				bboxCFrame, bboxSize = clonedObj.CFrame, clonedObj.Size
			end
	
			local center = bboxCFrame.Position
			local zoomDistance = math.max(bboxSize.X, bboxSize.Y, bboxSize.Z) * 1.5
			local minZoom, maxZoom = 5, 250
	
			local function updateCamera()
				camera.CFrame = CFrame.new(center + Vector3.new(0, zoomDistance / 2, zoomDistance), center)
			end
	
			updateCamera()
	
			local rotating = false
			local lastMousePos = nil
			local defaultMouseIconEnabled = game:GetService("UserInputService").MouseIconEnabled
	
			viewportFrame.InputBegan:Connect(function(input)
				if input.UserInputType == Enum.UserInputType.MouseButton1 then
					rotating = true
					lastMousePos = game:GetService("UserInputService"):GetMouseLocation()
					game:GetService("UserInputService").MouseIconEnabled = false
				end
			end)
	
			viewportFrame.InputEnded:Connect(function(input)
				if input.UserInputType == Enum.UserInputType.MouseButton1 then
					rotating = false
					game:GetService("UserInputService").MouseIconEnabled = defaultMouseIconEnabled
				end
			end)
	
			viewportFrame.InputChanged:Connect(function(input)
				if input.UserInputType == Enum.UserInputType.MouseWheel then
					zoomDistance = math.clamp(zoomDistance - input.Position.Z * 2, minZoom, maxZoom)
					updateCamera()
				end
			end)
	
			game:GetService("RunService").RenderStepped:Connect(function()
				if rotating then
					local newMousePos = game:GetService("UserInputService"):GetMouseLocation()
					local delta = newMousePos - lastMousePos
	
					local dx = delta.X * 0.005
					local dy = delta.Y * 0.005
	
					if clonedObj:IsA("Model") and clonedObj.PrimaryPart then
						clonedObj:SetPrimaryPartCFrame(
							clonedObj.PrimaryPart.CFrame * CFrame.Angles(-dy, -dx, 0)
						)
					elseif clonedObj:IsA("BasePart") then
						clonedObj.CFrame = clonedObj.CFrame * CFrame.Angles(-dy, -dx, 0)
					end
	
					lastMousePos = newMousePos
				end
			end)
	
	
		end)
	
		if not success then
			warn("[CreateViewPort] Error: " .. tostring(err))
		end
	end
	
			if obj then
