	local notifyCount = 0
	function notify(text)
	    local LnotifyCount = notifyCount+1
	    notifyCount = notifyCount+1
	    Message.Text = text
	    wait()
	    PersonalHint.Visible = true
	    PersonalHint:TweenSizeAndPosition(UDim2.new(0,1000,0,24),UDim2.new(0.5,-500,0,10), "Out", "Quart", 0.5)
	    Message:TweenSize(UDim2.new(0,1000,0,24), "Out", "Quart", 0.5)
	    wait(8)
	    if LnotifyCount == notifyCount then
	        PersonalHint:TweenSizeAndPosition(UDim2.new(0,0,0,24),UDim2.new(0.5,0,0,10), "Out", "Quart", 0.5)
	        Message:TweenSize(UDim2.new(0,0,0,24), "Out", "Quart", 0.5)
	        wait(0.5)
	        PersonalHint.Visible = false
	        notifyCount = 0
	    end
	end
	
	
	        
