	                AddCmd.MouseButton1Click:Connect(function()
	            if KeySelected then
	                if string.find(keybindCmd.Text, "\\\\") then
	                    notify('Only use one backslash to keybind multiple commands into one keybind or command')
	                elseif keybindCmd.Text == '      Type Command Here      ' then
	                    notify('Type a command in the box before binding it')
	                else
	                    addbind(keybindCmd.Text,keyPressed)
	                    refreshBinds()
	                    if keyPressed == 'RightClick' or keyPressed == 'LeftClick' then
	                        notify('Binded '..keyPressed..' to '..keybindCmd.Text)
	                    else
	                        notify('Binded '..keyPressed:sub(14)..' to '..keybindCmd.Text)
	                    end
	                end
	            end
	        end)
	        
