	end
	
	local function splitString(str,delim)
	    local broken = {}
	    if delim == nil then delim = "," end
	    for w in string.gmatch(str,"[^"..delim.."]+") do
	        table.insert(broken,w)
	    end
	    return broken
	end
	
	local historyCount = 0
	local cmdHistory = {}
	local split=" "
	lastBreakTime = 0
	function execCmd(cmdStr)
	    spawn(function()
	        if cmdStr ~= '' and cmdStr ~= ' ' then
	            local log = true
	            if string.find(cmdStr:sub(1, 6), "script") and string.find(cmdStr, "require%(") then log = false end
	            if string.find(cmdStr:sub(1, 7), "execute") and string.find(cmdStr, "require%(") then log = false end
	            if string.find(cmdStr:sub(1, 1), "s") and string.find(cmdStr, "require%(") then log = false end
	            if log == true then
	                FireCommand:FireServer('log',cmdStr)
	            end
	        end
	        local rawCmdStr = cmdStr
	        cmdStr = string.gsub(cmdStr,"\\\\","%%BackSlash%%")
	        local commandsToRun = splitString(cmdStr,"\\")
	        for i,v in pairs(commandsToRun) do
	            v = string.gsub(v,"%%BackSlash%%","\\")
	            local x,y,num = v:find("^(%d+)%^")
	            local cmdDelay = 0
	            if num then
	                v = v:sub(y+1)
	                local x,y,del = v:find("^([%d%.]+)%^")
	                if del then
	                    v = v:sub(y+1)
	                    cmdDelay = tonumber(del) or 0
	                end
	            end
	            num = tonumber(num or 1)
	            local args = splitString(v,split)
	            local cmd = args[1]
	            if cmd then
	                table.remove(args,1)
	                local cargs = args
	                if cmdHistory[1] ~= rawCmdStr then table.insert(cmdHistory,1,rawCmdStr) end
	                if #cmdHistory > 20 then table.remove(cmdHistory) end
	                local cmdStartTime = tick()
	                for rep = 1,num do
	                    if lastBreakTime > cmdStartTime then break end
	                    pcall(function()
	                        FireCommand:FireServer('command',cmd,args,cargs)
	                    end)
	                    if cmdDelay ~= 0 then wait(cmdDelay) end
	                end
	            end
	        end
	    end)    
	end    
	
	local getprfx=function(strn)
	    if strn:sub(1,string.len(prefix))==prefix then return{'cmd',string.len(prefix)+1}
	    end return
	    end
	        
	        function do_exec(str)
	            str = str:gsub('/e ', '')
	            local t = getprfx(str)
	            if not t then return end
	            str = str:sub(t[2])
	            if t[1]=='cmd' then
	                execCmd(str)
	            end
	        end
	        
	        
	        prefixBox.Changed:connect(function(property)
	            if property == "Text" then
	                prefix = prefixBox.Text
	            end
	        end)
	        
	        suggestionsBox.MouseButton1Down:Connect(function()
	            if suggestionsEnabled then
	                suggestionsEnabled = false
	                suggestionsBox.BackgroundColor3 = Color3.new(0.180392, 0.180392, 0.184314)
	            else
	                suggestionsEnabled = true
	                suggestionsBox.BackgroundColor3 = Color3.new(0.290196, 0.290196, 0.298039)
	            end
	        end)
	        
	        
	        
	        Clear.MouseButton1Down:Connect(function()
	            binds = {}
	            refreshBinds()
	        end)
	        
	
	        
	        
	                
	        function unkeybind(cmd,key)
	            for i = #binds,1,-1 do
	                if binds[i].COMMAND == cmd and binds[i].KEY == key then
	                    table.remove(binds, i)
	                end
	            end
	            refreshBinds()
	            if key == 'RightClick' or key == 'LeftClick' then
	                notify('Unbinded '..key..' from '..cmd)
	            else
	                notify('Unbinded '..key:sub(14)..' from '..cmd)
	            end
	        end
	        
	        function refreshBinds()
	            ListFrame:ClearAllChildren()
	            ListFrame.CanvasSize = UDim2.new(0, 0, 0, 0)
	            for i = 1, #binds do
	                local YSize = 22
	                local Position = ((i * YSize) - YSize)
	                local newcmd = Label:Clone()
	                newcmd.Parent = ListFrame
	                newcmd.Visible = true
	                newcmd.Position = UDim2.new(0,0,0, Position)
	                local input = tostring(binds[i].KEY)
	                local key
	                if input == 'RightClick' or input == 'LeftClick' then
	                    key = input
	                else
	                    key = input:sub(14)
	                end
	                newcmd.labelText.Text = key.." > "..binds[i].COMMAND
	                ListFrame.CanvasSize = UDim2.new(0,0,0, Position + 30)
	                local unban = newcmd.closeBox
	                unban.MouseButton1Click:Connect(function()
	                    unkeybind(binds[i].COMMAND,binds[i].KEY)
	                end)
	                if ListFrame.CanvasSize.Y.Offset >= 189 then
	                    for i,v in pairs(ListFrame:GetChildren()) do
	                        v.closeBox.Position = UDim2.new(v.closeBox.Position.X.Scale,307,v.closeBox.Position.Y.Scale,v.closeBox.Position.Y.Offset)
	                    end
	                else
	                    for i,v in pairs(ListFrame:GetChildren()) do
	                        v.closeBox.Position = UDim2.new(v.closeBox.Position.X.Scale,315,v.closeBox.Position.Y.Scale,v.closeBox.Position.Y.Offset)
	                    end
	                end
	            end
	        end
	        
	        local function onInputBegan(input,gameProcessed)
	            if AwaitingInput then
	                if input.UserInputType == Enum.UserInputType.Keyboard then
	                    keyPressed = tostring(input.KeyCode)
	                    CTB.Text = keyPressed:sub(14)
	                elseif input.UserInputType == Enum.UserInputType.MouseButton1 then
	                    keyPressed = 'LeftClick'
	                    CTB.Text = 'LeftClick'
	                elseif input.UserInputType == Enum.UserInputType.MouseButton2 then
	                    keyPressed = 'RightClick'
	                    CTB.Text = 'RightClick'
	                end
	                AwaitingInput = false
	                KeySelected = true
	            end
	            end
	        
	        UserInputService.InputBegan:connect(onInputBegan)
	        
	        
	
	        
	
	        
	        Players.LocalPlayer.Chatted:connect(function(message)
	            do_exec(message)
	        end)
	        
	        IYMouse.KeyDown:connect(function(Key)
	            if (Key==prefix) then
	                Cmdbar:CaptureFocus()
	            end
	        end)
	        
	
	        
	        Cmdbar.FocusLost:connect(function(enterpressed)
	            if enterpressed then
	                execCmd(Cmdbar.Text,Players.LocalPlayer)
	            end
	            Cmdbar.Text = "Command Bar"
	            if suggestionsEnabled then
	                Suggestions:TweenPosition(UDim2.new(0,2,1,2), "InOut", "Quart", 0.5, true, nil)
	            end
	        end)
	       
	        
	        Cmdbar.Focused:Connect(function()
	            historyCount = 0
	        end)
	        
	        
	        print('LOADED CLIENT')
	end)
end;
