	                                    end
	                                end)
	                            end
	
	                            if math.random(1,50) == math.random(1,50) then
	                                Part:Destroy()
	                            end
	                        end
	                    end)
	
	                    C4:Destroy()
	                    task.wait(0.25)
	                end
	            end
	        end
	    end
	end)
	end)
end;
