	local function IRPF_fake_script() -- TextButton_4.LocalScript 
		local script = Instance.new('LocalScript', TextButton_4)
	
		local TextButton = script.Parent
		
		TextButton.MouseButton1Click:Connect(function()
			local player = game.Players.LocalPlayer
			local PlayerGui = player:WaitForChild("PlayerGui") -- Ensure PlayerGui exists
		
			-- Create the ScreenGui and parent it correctly
			local ScreenGui = Instance.new("ScreenGui")
			ScreenGui.Parent = PlayerGui
		
			local Frame = Instance.new("Frame")
			Frame.Parent = ScreenGui
			Frame.Size = UDim2.new(0, 300, 0, 200) -- Visible size
			Frame.Position = UDim2.new(0.3, 0, 0.3, 0) -- Adjusted position
			Frame.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
			Frame.BorderSizePixel = 2
			Frame.BorderColor3 = Color3.fromRGB(0, 0, 0)
		
			local ImageLabel = Instance.new("ImageLabel")
			ImageLabel.Parent = Frame
			ImageLabel.BackgroundTransparency = 1
			ImageLabel.Size = UDim2.new(0, 150, 0, 150)
			ImageLabel.Position = UDim2.new(0.25, 0, 0.15, 0)
			ImageLabel.Image = "rbxassetid://158118263"
		
			local TextLabel = Instance.new("TextLabel")
			TextLabel.Parent = Frame
			TextLabel.BackgroundTransparency = 1
			TextLabel.Size = UDim2.new(1, 0, 0, 50)
			TextLabel.Position = UDim2.new(0, 0, 0.75, 0)
			TextLabel.Font = Enum.Font.FredokaOne
			TextLabel.Text = "get pwnzed by team c00lkidd"
			TextLabel.TextColor3 = Color3.fromRGB(0, 0, 0)
			TextLabel.TextScaled = true
			TextLabel.TextWrapped = true
		end)
	end
	coroutine.wrap(IRPF_fake_script)()
