	local TweenService = game:GetService("TweenService")
	local RunService = game:GetService("RunService")
	
	local Module = {}
	local ScrollingObjects = {}
	
	local function removeInput(ScrollingObject: ScrollingFrame)
		local index = table.find(ScrollingObjects, ScrollingObject)
		if index then
			table.remove(ScrollingObjects, index)
		end
	end
	
	local function lerp(vmin, vmax, vpercent)
		return vmin + (vmax - vmin) * vpercent
	end
	
	local function insertInput(guiObject: ScrollingFrame, scrollSpeed: number, theAbsoluteCanvasSize: Vector2)
		local customAbsoluteCanvasSize = guiObject.AbsoluteCanvasSize + theAbsoluteCanvasSize
		local SmoothingEnabled = true
		local SmoothingFactor = scrollSpeed
		local content = guiObject
	
		content.ScrollingEnabled = not SmoothingEnabled
	
		local input = content:Clone()
		input.CanvasSize = UDim2.fromOffset(customAbsoluteCanvasSize.X, customAbsoluteCanvasSize.Y)
		input:ClearAllChildren()
		input.BackgroundTransparency = 1
		input.ScrollBarImageTransparency = 1
		input.ZIndex = content.ZIndex + 2
		input.Name = "_smoothinputframe"
		input.ScrollingEnabled = SmoothingEnabled
		input.Parent = content.Parent
	
		local Connection1 = content.ChildAdded:Connect(function()
			input.CanvasSize = UDim2.fromOffset(customAbsoluteCanvasSize.X, customAbsoluteCanvasSize.Y)
		end)
	
		local Connection2 = content.ChildRemoved:Connect(function()
			input.CanvasSize = UDim2.fromOffset(customAbsoluteCanvasSize.X, customAbsoluteCanvasSize.Y)
		end)
	
		local Connection3 = input:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
			if not SmoothingEnabled then
				content.CanvasPosition = input.CanvasPosition
			end
		end)
	
		local function syncProperty(prop)
			content:GetPropertyChangedSignal(prop):Connect(function()
				if prop == "ZIndex" then
					input[prop] = content[prop] + 1
				else
					input[prop] = content[prop]
				end
			end)
		end
	
		for _, prop in ipairs({
			"CanvasSize", "Position", "Rotation", "ScrollingDirection", "ScrollBarThickness",
			"BorderSizePixel", "ElasticBehavior", "SizeConstraint", "ZIndex",
			"BorderColor3", "Size", "AnchorPoint", "Visible"
		}) do
			syncProperty(prop)
		end
	
		local Connection4 = RunService.RenderStepped:Connect(function(dt)
			if SmoothingEnabled then
				local a = content.CanvasPosition
				local b = input.CanvasPosition
				local c = SmoothingFactor
				local d = lerp(a, b, 1 - c ^ dt)
				content.CanvasPosition = d
			end
		end)
	
		local Connection5 = content.AncestryChanged:Connect(function()
			if not content:IsDescendantOf(game) then
				input:Destroy()
				Connection4:Disconnect()
			end
		end)
	
		table.insert(ScrollingObjects, {
			Scrollify = true,
			Object = guiObject,
			Input = input,
			Connections = {
				Connection1 = Connection1,
				Connection2 = Connection2,
				Connection3 = Connection3,
				Connection4 = Connection4,
				Connection5 = Connection5
			}
		})
	end
	
	Module.removeInput = removeInput
	Module.insertInput = insertInput
	
	Module.insertInput(ScrollingFrame, 0.05, Vector2.new(0, 0))
	
	
	local SearchFunction = function(Search, ScrollingFrame : ScrollingFrame)
	    local InputFrame : Instance = ScrollingFrame.Parent:WaitForChild("_smoothinputframe")
	    local function Match(name, str)
	        return string.find(string.lower(name), string.lower(str)) ~= nil
	    end
	    local function IndexContents(str : string)
	        for _, v in next, ScrollingFrame:GetChildren() do
	            if v:IsA("GuiObject") then
	                v.Visible = Match(v.Name, str)
	            end
	        end
	    end
	    local function SearchChanged()
	        IndexContents(Search.Text)
	    end
	    local function ScrollingFrameChildAdded()
	        Search.Text = ''
	        IndexContents('')
	    end
	    local function ScrollingFrameAttributeChanged()
	        Search.Text = ''
	        IndexContents('')
	    end
	    local function ScrollingFramePropertyChanged()
	        InputFrame.CanvasSize = UDim2.fromOffset(ScrollingFrame.AbsoluteCanvasSize.X, ScrollingFrame.AbsoluteCanvasSize.Y)
	    end
	    Search:GetPropertyChangedSignal("Text"):Connect(SearchChanged)
	    ScrollingFrame.ChildAdded:Connect(ScrollingFrameChildAdded)
	    ScrollingFrame.AttributeChanged:Connect(ScrollingFrameAttributeChanged)
	    ScrollingFrame:GetPropertyChangedSignal("AbsoluteCanvasSize"):Connect(ScrollingFramePropertyChanged)
	    IndexContents('')
	end
	
	SearchFunction(Search, ScrollingFrame)
	end)
end;
