	chara.Animate.Parent = nil
	
	local newMotor = function(part0, part1, c0, c1)
		local w = Create("Motor"){
			Parent = part0,
			Part0 = part0,
			Part1 = part1,
			C0 = c0,
			C1 = c1,
		}
		return w
	end
	
	function clerp(a, b, t)
		return a:lerp(b, t)
	end
	
	RootCF = CFrame.fromEulerAnglesXYZ(-1.57, 0, 3.14)
	NeckCF = CFrame.new(0, 1, 0, -1, 0, 0, 0, 0, 1, 0, 1, 0)
	
	local RW = newMotor(Torso, RightArm, CFrame.new(1.5, 0, 0), CFrame.new())
	local LW = newMotor(Torso, LeftArm, CFrame.new(-1.5, 0, 0), CFrame.new())
	local RH = newMotor(Torso, RightLeg, CFrame.new(0.5, -2, 0), CFrame.new())
	local LH = newMotor(Torso, LeftLeg, CFrame.new(-0.5, -2, 0), CFrame.new())
	RootJoint.C1 = CFrame.new()
	RootJoint.C0 = CFrame.new()
	Torso.Neck.C1 = CFrame.new()
	Torso.Neck.C0 = CFrame.new(0, 1.5, 0)
	
	local rarmc1 = RW.C1
	local larmc1 = LW.C1
	local rlegc1 = RH.C1
	local llegc1 = LH.C1
	local resetc1 = false
	
	function PlayAnimationFromTable(tbl, speed, bool)
		RootJoint.C0 = clerp(RootJoint.C0, tbl[1], speed)
		Torso.Neck.C0 = clerp(Torso.Neck.C0, tbl[2], speed)
		RW.C0 = clerp(RW.C0, tbl[3], speed)
		LW.C0 = clerp(LW.C0, tbl[4], speed)
		RH.C0 = clerp(RH.C0, tbl[5], speed)
		LH.C0 = clerp(LH.C0, tbl[6], speed)
		if bool == true then
			if resetc1 == false then
				resetc1 = true
				RootJoint.C1 = RootJoint.C1
				Torso.Neck.C1 = Torso.Neck.C1
				RW.C1 = rarmc1
				LW.C1 = larmc1
				RH.C1 = rlegc1
				LH.C1 = llegc1
			end
		end
	end
	
	ArtificialHB = Instance.new("BindableEvent", script)
	ArtificialHB.Name = "Heartbeat"
	script:WaitForChild("Heartbeat")
	frame = 0.03333333333333
	tf = 0
	allowframeloss = false
	tossremainder = false
	lastframe = tick()
	script.Heartbeat:Fire()
	game:GetService("RunService").Heartbeat:Connect(function(s, p)
		tf = tf + s
		if tf >= frame then
			if allowframeloss then
				script.Heartbeat:Fire()
				lastframe = tick()
			else
				for i = 1, math.floor(tf / frame) do
					script.Heartbeat:Fire()
				end
				lastframe = tick()
			end
			if tossremainder then
				tf = 0
			else
				tf = tf - frame * math.floor(tf / frame)
			end
		end
	end)
	
	function swait(num)
		if num == 0 or num == nil then
			ArtificialHB.Event:Wait()
		else
			for i = 0, num do
				ArtificialHB.Event:Wait()
			end
		end
	end
	
	function RemoveOutlines(part)
		part.TopSurface, part.BottomSurface, part.LeftSurface, part.RightSurface, part.FrontSurface, part.BackSurface = 10, 10, 10, 10, 10, 10
	end
	
