				local function LAVB_fake_script() -- script.LocalScript
		local raggy = Instance.new('Script', dude)
	local character = chara
	 
	function recurse(root,callback,i)
	    i= i or 0
	    for _,v in pairs(root:GetChildren()) do
	        i = i + 1
	        callback(i,v)
	        
	        if #v:GetChildren() > 0 then
	            i = recurse(v,callback,i)
	        end
	    end
	    
	    return i
	end
	 
	function ragdollJoint(part0, part1, attachmentName, className, properties)
	    if part0 and part1 then
	        attachmentName = attachmentName.."RigAttachment"
	        local constraint = Instance.new(className.."Constraint")
	        constraint.Attachment0 = part0:FindFirstChild(attachmentName)
	        constraint.Attachment1 = part1:FindFirstChild(attachmentName)
	        constraint.Name = "RagdollConstraint"..part1.Name
	        
	        for _,propertyData in next,properties or {} do
	            constraint[propertyData[1]] = propertyData[2]
	        end
	        
	        constraint.Parent = character
	    end
	end
	 
	function getAttachment0(attachmentName)
	    for _,child in next,character:GetChildren() do
	        local attachment = child:FindFirstChild(attachmentName)
	        if attachment then
	            return attachment
	        end
	    end
	end
	 
	character:FindFirstChildOfClass("Humanoid").Died:connect(function()
	    game:GetService("Debris"):AddItem(character,10)
	    local camera = workspace.CurrentCamera
	    if camera.CameraSubject == character.Humanoid then--If developer isn't controlling camera
