	local avilable = {}
	function Triformation(reset)
		local Formate = GiveFormate()
	    if Formate ~= nil then
		   local q = Formate
		   if string.find((avilable[q]),'/',1) then
			  local p = string.find((avilable[q]),'/',1)
			  local mz = string.sub((avilable[q]),p+1)
			  local mx = string.sub((avilable[q]),3, p-1)
			  avilable[q] = mx..'/'..mz
			  return mx, mz
		   end
	    elseif Formate == nil then
		x = x + 1
	    if x == previous then
	       z = z + 1
	       previous = previous + 1
	       x = -z
	    end
		table.insert(avilable, x .. '/' .. z)
	    if reset == true then
		   x = 0
		   z = 0
		   previous = 1
		   avilable = {}
	    end
	    return x, z
		end
	end
	function RemoveFormate(p)
	   for b,v in pairs(avilable) do
	      if v == p then
		      avilable[b] = 'D '.. v 
	      end
	   end
	end
	function GiveFormate()
	   for c,v in pairs(avilable) do
