		   elseif RM == 2 then
		     DR = DR + 1
		     namebillboard.StudsOffset = Vector3.new(0, 0.75+2.5*math.sin(DR/(timr/2.5)), 2)
		     textt.TextStrokeTransparency = i/timr
		     textt.TextTransparency = i/timr
		     textt.Rotation = 7.5*-math.cos(DR/(timr/2))
		   end
	   end
